using System.Reflection;
using System.Text.Json;
using Yukkuri.Simulation;

// Deterministic rule regression. Placements use public APIs; needs and exact
// boundary poses are synthetic fixtures, not claims of UI or long-run coverage.
int passed=0,failed=0;
void Require(bool ok,string message){if(!ok)throw new Exception(message);}
void Check(string name,Action body){try{body();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+e.Message);}}
void Step(WorldSimulation s){var c=s.State.Creatures[0];double x=c.X,z=c.Z;s.AdvanceInteractionPresentation(.05);s.Advance(.05);Require(Math.Sqrt(Math.Pow(c.X-x,2)+Math.Pow(c.Z-z,2))<.25,"movement teleported");}
void Seconds(WorldSimulation s,double seconds){for(int n=0;n<(int)Math.Round(seconds/.05);n++)Step(s);}
ShelterState Home(WorldSimulation s)=>s.State.Shelters.Single();
bool Overlap(WorldSimulation s){var c=s.State.Creatures[0];var h=Home(s);return ShelterGeometry.OverlapsInterior(c.X-h.X,c.Z-h.Z,WorldSimulation.ShelterPassageRadius(c));}
void Sync(WorldSimulation s)=>typeof(WorldSimulation).GetMethod("SynchronizeShelters",BindingFlags.Instance|BindingFlags.NonPublic)!.Invoke(s,null);
WorldSimulation Reload(WorldSimulation s){SaveStore.Validate(s.State);var state=JsonSerializer.Deserialize<WorldState>(JsonSerializer.Serialize(s.State,SaveStore.JsonOptions),SaveStore.JsonOptions)!;SaveStore.Validate(state);return new(state);}
WorldSimulation Fixture(ShelterVisitPhase phase=ShelterVisitPhase.Entering,bool ball=true,double ballZ=1){
 var s=WorldSimulation.CreateInteractionPlaytest(20261031);s.State.RoomObjects.Clear();s.State.PlayerX=6;s.State.PlayerZ=6;s.SetAutonomousBreeding(false);
 for(int n=0;n<s.State.Creatures.Count;n++){var q=s.State.Creatures[n];q.X=q.TargetX=-5+n*4;q.Z=q.TargetZ=-5;q.Fullness=q.Health=q.Energy=q.Interaction.Hydration=100;q.Fear=q.Pain=0;q.Interaction.Emotion.Alarm=0;q.Interaction.Emotion.SafeSeconds=100;q.Interaction.NextAutonomyAt=q.DecisionIn=q.Family.NextSocialAt=q.Family.NextCareAt=10000;}
 Require(s.BuyShelter()&&s.PlaceShelter(0,0).Success,"public shelter placement failed");var c=s.State.Creatures[0];c.X=c.TargetX=0;c.Z=c.TargetZ=3;c.Fear=50;c.Interaction.Emotion.Alarm=30;c.Interaction.Emotion.SafeSeconds=0;
 for(int n=0;n<800&&Home(s).Phase!=phase;n++)Step(s);
 Require(Home(s).Phase==phase&&Home(s).GuestId==c.Id,"natural visit did not reach requested phase");
 if(ball){Require(s.BuyShopProduct("ball"),"buy ball");Require(s.ExecuteInteraction(s.State.Creatures[1].Id,new InteractionInput(InteractionAction.GiveBall,BodyPart.Side,X:0,Z:0)).Success,"give ball");var b=s.State.RoomObjects.Single(o=>o.Kind==RoomObjectKind.Ball);Require(s.MoveLooseObject(b.Id,0,ballZ),"public ball movement failed");}
 SaveStore.Validate(s.State);return s;
}
void Need(Creature c,bool water){if(water)c.Interaction.Hydration=10;else c.Fullness=10;}
foreach(bool water in new[]{false,true}){
 string kind=water?"water":"food";
 Check("blocked entering releases for "+kind,()=>{var s=Fixture();var c=s.State.Creatures[0];Require(!Overlap(s),"fixture already overlaps");Need(c,water);SaveStore.Validate(s.State);Seconds(s,30);SaveStore.Validate(s.State);Require(Home(s).GuestId==null&&Home(s).Phase==ShelterVisitPhase.Empty,"outside reservation retained after 30 seconds");Require(c.Activity==(water?"四处找水水":"四处找能吃的叶子"),"natural search did not resume: "+c.Activity+" target="+c.Interaction.ResourceTargetId);});
 Check("public supply eventually consumed after blocked entering "+kind,()=>{var s=Fixture(ballZ:.9);var c=s.State.Creatures[0];Require(c.Z-.9>WorldSimulation.ShelterPassageRadius(c)+.32,"supply fixture starts overlapping ball");Require(s.PlaceInteractionSupply(water?InteractionAction.PlaceWater:InteractionAction.PlaceMeal,0,4).Success,"public supply placement failed");Need(c,water);SaveStore.Validate(s.State);bool released=false;double max=10;for(int n=0;n<2400;n++){Step(s);released|=Home(s).GuestId==null;if(released&&(water?NaturalResources.WantsWater(c):NaturalResources.WantsFood(c)))Require(Home(s).GuestId==null,"urgent need reentered shelter");max=Math.Max(max,water?c.Interaction.Hydration:c.Fullness);}SaveStore.Validate(s.State);Require(released,"reservation never released");Console.WriteLine($"EVIDENCE supply water={water} maxNeed={max:F3} finalPosition={c.X:F3},{c.Z:F3} released={released}");Require(Math.Abs(c.Z-2.02)+Math.Abs(c.X)>.1,"supply consumer never moved");Require(max>15,"real supply was not consumed: "+max+" activity="+c.Activity+" pos="+c.X+","+c.Z+" target="+c.Interaction.ResourceTargetId);});
 Check("unobstructed entering releases for "+kind,()=>{var s=Fixture(ball:false);Need(s.State.Creatures[0],water);Seconds(s,1);SaveStore.Validate(s.State);Require(Home(s).GuestId==null,"clear outside reservation retained");});
 Check("approaching control "+kind,()=>{var s=Fixture(ShelterVisitPhase.Approaching);Need(s.State.Creatures[0],water);Seconds(s,1);SaveStore.Validate(s.State);Require(Home(s).GuestId==null,"approaching reservation retained");});
 Check("inside walks out for "+kind,()=>{var s=Fixture(ShelterVisitPhase.Inside,false);Need(s.State.Creatures[0],water);Seconds(s,.25);Require(Home(s).GuestId==s.State.Creatures[0].Id&&Home(s).Phase==ShelterVisitPhase.Exiting,"inside ownership released early");for(int n=0;n<800&&Home(s).GuestId!=null;n++)Step(s);SaveStore.Validate(s.State);Require(Home(s).GuestId==null&&!Overlap(s),"body did not actually exit");});
 Check("pause and JSON resume "+kind,()=>{var s=Fixture();var c=s.State.Creatures[0];Need(c,water);s.State.Settings.Pause=true;double z=c.Z,clock=s.State.WorldSeconds;Seconds(s,1);Require(Home(s).GuestId==c.Id&&c.Z==z&&s.State.WorldSeconds==clock,"paused visit advanced");s=Reload(s);c=s.State.Creatures[0];Require(c.Z==z,"load teleported");s.State.Settings.Pause=false;s.State.Mode=PlayMode.CloseUp;clock=s.State.WorldSeconds;z=c.Z;Seconds(s,1);Require(c.Z==z&&s.State.WorldSeconds==clock,"closeup visit advanced");s.State.Mode=PlayMode.Management;Seconds(s,30);SaveStore.Validate(s.State);Require(Home(s).GuestId==null,"resumed reservation retained");});
}
Check("blocked entering without priority retains reservation",()=>{var s=Fixture();var c=s.State.Creatures[0];double x=c.X,z=c.Z;Seconds(s,30);SaveStore.Validate(s.State);Require(Home(s).GuestId==c.Id&&Home(s).Phase==ShelterVisitPhase.Entering&&Home(s).BlockedSeconds>=29,"nonurgent blocked visit changed");Require(c.X==x&&c.Z==z,"ball no longer blocks doorway");});
foreach(double offset in new[]{.001,0,-.001})Check("exact interior boundary offset "+offset,()=>{var s=Fixture(ball:false);var c=s.State.Creatures[0];var h=Home(s);c.Z=c.TargetZ=ShelterGeometry.InteriorDepth*.5+WorldSimulation.ShelterPassageRadius(c)+offset;Need(c,false);SaveStore.Validate(s.State);Require(Overlap(s)==(offset<0),"boundary overlap semantics changed");double x=c.X,z=c.Z;Sync(s);Require(c.X==x&&c.Z==z,"synchronization moved body");Require(offset<0?h.GuestId==c.Id&&h.ExitRequested:h.GuestId==null,"wrong boundary reservation outcome");SaveStore.Validate(s.State);});
foreach(string priority in new[]{"pain","energy","family"})Check("existing priority "+priority,()=>{var s=Fixture();var c=s.State.Creatures[0];if(priority=="pain")c.Pain=40;else if(priority=="energy")c.Energy=21.99;else c.Family.CompanionTargetId=s.State.Creatures[1].Id;SaveStore.Validate(s.State);double x=c.X,z=c.Z;Sync(s);Require(Home(s).GuestId==null,"existing priority was suppressed");Require(c.X==x&&c.Z==z,"priority release teleported");SaveStore.Validate(s.State);});
foreach(string threshold in new[]{"food","water","pain","energy"})Check("unchanged nonpriority threshold "+threshold,()=>{var s=Fixture();var c=s.State.Creatures[0];if(threshold=="food")c.Fullness=70;else if(threshold=="water")c.Interaction.Hydration=70;else if(threshold=="pain")c.Pain=39.99;else c.Energy=22;SaveStore.Validate(s.State);Sync(s);Require(Home(s).GuestId==c.Id&&!Home(s).ExitRequested,"nonpriority threshold changed");SaveStore.Validate(s.State);});
// Direct method coverage isolates an urgent need arising after synchronization.
foreach(bool water in new[]{false,true})Check("active visitor direct release "+water,()=>{var s=Fixture();var c=s.State.Creatures[0];Need(c,water);SaveStore.Validate(s.State);double x=c.X,z=c.Z;bool handled=(bool)typeof(WorldSimulation).GetMethod("TryActiveShelter",BindingFlags.Instance|BindingFlags.NonPublic)!.Invoke(s,new object[]{c,.25})!;Require(!handled&&Home(s).GuestId==null,"active visit swallowed priority need");Require(c.X==x&&c.Z==z,"active release teleported");SaveStore.Validate(s.State);});
foreach(double fullness in new[]{55d,54.99})Check("existing symptomatic hunger boundary "+fullness,()=>{var s=Fixture();var c=s.State.Creatures[0];c.Interaction.Digestion.SymptomsRemaining=30;c.Interaction.Digestion.Severity=10;c.Fullness=fullness;SaveStore.Validate(s.State);Sync(s);Require(fullness<55?Home(s).GuestId==null:Home(s).GuestId==c.Id,"symptomatic hunger threshold changed");SaveStore.Validate(s.State);});
Check("nonoverlapping public ball still blocks entry without priority",()=>{var s=Fixture(ballZ:.9);var c=s.State.Creatures[0];double z=c.Z;Require(c.Z-.9>WorldSimulation.ShelterPassageRadius(c)+.32,"fixture overlaps ball");Seconds(s,30);Require(Home(s).GuestId==c.Id&&Home(s).BlockedSeconds>=29&&c.Z==z,"clearance control failed");SaveStore.Validate(s.State);});
Check("partially overlapping entrant takes real exit",()=>{var s=Fixture(ball:false);var c=s.State.Creatures[0];c.Z=c.TargetZ=ShelterGeometry.InteriorDepth*.5+WorldSimulation.ShelterPassageRadius(c)-.001;Need(c,false);SaveStore.Validate(s.State);Sync(s);Require(Home(s).GuestId==c.Id&&Home(s).ExitRequested,"overlap released prematurely");for(int n=0;n<800&&Home(s).GuestId!=null;n++)Step(s);Require(Home(s).GuestId==null&&!Overlap(s),"partial body did not really exit");SaveStore.Validate(s.State);});
Console.WriteLine($"RESULT passed={passed} failed={failed} total={passed+failed}");return failed==0?0:1;
